import { zodResolver } from '@hookform/resolvers/zod';
import React, { useEffect, useMemo, useState } from 'react';
import { Controller, useForm } from 'react-hook-form';
import type { FormField, GroupDescriptor, Schema, SpawnClient, SubmitResult, Verdict } from '@spawnflow/core';
import { compileForm, fieldVerdicts, normalize } from '@spawnflow/core';
import { defaultWidgets, type WidgetComponent } from './widgets';

export interface SpawnFormProps {
  /** Pre-fetched contract schema (resolved or variants)… */
  schema?: Schema;
  /** …or let the form fetch it. */
  client?: SpawnClient;
  subject?: string;
  id?: number;
  /** Variant to render when the schema has multiple (create forms). */
  context?: string;
  /** Initial values (e.g. the record being edited). */
  values?: Record<string, unknown>;
  /** Called with validated values. Return a SubmitResult to surface server errors. */
  onSubmit?: (values: Record<string, unknown>) => Promise<SubmitResult | void> | SubmitResult | void;
  submitLabel?: string;
  /** Override or extend the widget registry (widget name → component). */
  widgets?: Record<string, WidgetComponent>;
  /** Hide read-only fields instead of rendering them disabled. */
  hideReadOnly?: boolean;
}

/**
 * Schema-driven, context-aware form. Widgets come from the field
 * descriptors, client-side validation from the structured rules (compiled
 * to Zod), editability from the resolved context. Non-editable fields
 * render disabled; write-only confirmations ('confirmed' rule) get a
 * paired input automatically.
 */
export function SpawnForm({
  schema: givenSchema,
  client,
  subject,
  id,
  context,
  values,
  onSubmit,
  submitLabel = 'Save',
  widgets,
  hideReadOnly = false,
}: SpawnFormProps) {
  const [fetched, setFetched] = useState<Schema | null>(null);
  const [fetchError, setFetchError] = useState<string | null>(null);

  useEffect(() => {
    if (givenSchema || !client || !subject) return;
    let cancelled = false;
    client
      .schema(subject, id)
      .then((s) => !cancelled && setFetched(s))
      .catch((e: Error) => !cancelled && setFetchError(e.message));
    return () => {
      cancelled = true;
    };
  }, [givenSchema, client, subject, id]);

  const schema = givenSchema ?? fetched;

  if (fetchError) return <p className="text-sm text-destructive">{fetchError}</p>;
  if (!schema) return <p className="text-sm text-muted-foreground">Loading schema…</p>;

  return (
    <ResolvedForm
      key={`${schema.resource}:${context ?? ''}:${id ?? 'new'}`}
      schema={schema}
      context={context}
      values={values}
      onSubmit={onSubmit}
      submitLabel={submitLabel}
      widgets={widgets}
      hideReadOnly={hideReadOnly}
      client={client}
      subject={subject ?? schema.resource}
      id={id}
    />
  );
}

function ResolvedForm({
  schema,
  context,
  values,
  onSubmit,
  submitLabel,
  widgets,
  hideReadOnly,
  client,
  subject,
  id,
}: Required<Pick<SpawnFormProps, 'schema' | 'submitLabel' | 'hideReadOnly'>> &
  Pick<SpawnFormProps, 'context' | 'values' | 'onSubmit' | 'widgets' | 'client' | 'id'> & { subject: string }) {
  const normalized = useMemo(() => normalize(schema!, context), [schema, context]);
  const { context: resolvedContext, fields, groups } = normalized;

  const zodSchema = useMemo(() => compileForm(fields), [fields]);
  const registry = { ...defaultWidgets, ...widgets };

  const defaults: Record<string, unknown> = {};
  for (const field of fields) {
    if (!field.editable) continue;
    defaults[field.name] = values?.[field.name] ?? field.default ?? (field.type === 'bool' ? false : undefined);
  }

  const form = useForm<Record<string, any>>({
    resolver: zodResolver(zodSchema as never),
    defaultValues: defaults,
    mode: 'onBlur',
  });
  const [formError, setFormError] = useState<string | null>(null);
  const [succeeded, setSucceeded] = useState(false);

  const submit = form.handleSubmit(async (data) => {
    setFormError(null);
    setSucceeded(false);
    return await onValid(data as Record<string, unknown>);
  }, () => {
    // Client validation blocked the submit — clear stale success state.
    setFormError(null);
    setSucceeded(false);
  });

  async function onValid(data: Record<string, unknown>) {
    // Mirror the server's clear-on-ineligible semantics: values of
    // rule-ineligible fields are discarded, not submitted.
    const finalVerdicts = fieldVerdicts(normalized, data);
    for (const [name, verdict] of Object.entries(finalVerdicts)) {
      if (!verdict.visible || !verdict.enabled) delete data[name];
    }

    const result = onSubmit
      ? await onSubmit(data as Record<string, unknown>)
      : client
        ? await client.submit(subject, data as Record<string, unknown>, id)
        : undefined;

    if (result && !result.ok) {
      for (const [name, messages] of Object.entries(result.errors)) {
        form.setError(name, { type: 'server', message: messages[0] });
      }
      if (result.message && Object.keys(result.errors).length === 0) setFormError(result.message);
      return;
    }
    setSucceeded(true);
  }

  // Live rule verdicts: re-evaluated as values change, mirroring the
  // server's Eligibility::fieldVerdicts(). Hidden fields unmount;
  // disabled fields render but reject input.
  const watched = form.watch();
  const verdicts: Record<string, Verdict> = fieldVerdicts(normalized, watched);

  const visible = fields
    .filter((f) => f.visible || f.editable)
    .filter((f) => !hideReadOnly || f.editable)
    .filter((f) => verdicts[f.name]?.visible !== false);

  const ungrouped = visible.filter((f) => !f.group);
  const sections = groups
    .map((group) => ({ group, members: visible.filter((f) => f.group === group.name) }))
    .filter(({ members }) => members.length > 0);

  const row = (field: FormField) => (
    <FieldRow
      key={field.name}
      field={field}
      form={form}
      registry={registry}
      client={client}
      subject={subject}
      values={values}
      disabled={verdicts[field.name]?.enabled === false}
    />
  );

  return (
    <form onSubmit={(e) => void submit(e)} className="space-y-4" data-context={resolvedContext}>
      {ungrouped.map(row)}
      {sections.map(({ group, members }) => (
        <fieldset key={group.name} className="space-y-4 rounded-lg border p-4" data-group={group.name}>
          <legend className="px-1 text-sm font-medium">{group.label}</legend>
          {members.map(row)}
        </fieldset>
      ))}
      {formError && <p className="text-sm text-destructive">{formError}</p>}
      {succeeded && <p className="text-sm text-emerald-600">Saved.</p>}
      <button
        type="submit"
        disabled={form.formState.isSubmitting || fields.every((f) => !f.editable)}
        className="inline-flex h-9 items-center rounded-md bg-primary px-4 text-sm font-medium text-primary-foreground shadow hover:bg-primary/90 disabled:pointer-events-none disabled:opacity-50"
      >
        {form.formState.isSubmitting ? 'Saving…' : submitLabel}
      </button>
    </form>
  );
}

function FieldRow({
  field,
  form,
  registry,
  client,
  subject,
  values,
  disabled = false,
}: {
  field: FormField;
  form: ReturnType<typeof useForm>;
  registry: Record<string, WidgetComponent>;
  client?: SpawnClient;
  subject: string;
  values?: Record<string, unknown>;
  disabled?: boolean;
}) {
  const Widget = registry[field.widget] ?? registry.input;
  const confirmed = field.rules.some((r) => r.rule === 'confirmed');
  const serverOnly = field.rules.filter((r) => r.serverOnly).map((r) => r.rule);

  if (!field.editable) {
    const raw = values?.[field.name];
    return (
      <div className="space-y-1.5">
        <Label field={field} />
        <input
          className="flex h-9 w-full rounded-md border border-input bg-muted/50 px-3 py-1 text-sm text-muted-foreground"
          value={raw === undefined || raw === null ? '—' : String(raw)}
          disabled
        />
      </div>
    );
  }

  return (
    <>
      <Controller
        name={field.name as never}
        control={form.control}
        render={({ field: rhf, fieldState }) => (
          <div className="space-y-1.5">
            {field.widget !== 'checkbox' && <Label field={field} serverOnly={serverOnly} />}
            <Widget
              field={field}
              value={rhf.value}
              onChange={rhf.onChange}
              onBlur={rhf.onBlur}
              disabled={disabled}
              error={fieldState.error?.message}
              client={client}
              subject={subject}
            />
            {fieldState.error && <p className="text-sm text-destructive">{fieldState.error.message}</p>}
          </div>
        )}
      />
      {confirmed && (
        <Controller
          name={`${field.name}_confirmation` as never}
          control={form.control}
          render={({ field: rhf, fieldState }) => (
            <div className="space-y-1.5">
              <label className="text-sm font-medium leading-none">Confirm {field.label.toLowerCase()}</label>
              <input
                type="password"
                autoComplete="new-password"
                className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                value={(rhf.value as string) ?? ''}
                onChange={(e) => rhf.onChange(e.target.value)}
                onBlur={rhf.onBlur}
              />
              {fieldState.error && <p className="text-sm text-destructive">{fieldState.error.message}</p>}
            </div>
          )}
        />
      )}
    </>
  );
}

function Label({ field, serverOnly = [] }: { field: FormField; serverOnly?: string[] }) {
  const required = field.rules.some((r) => r.rule === 'required');
  return (
    <label className="flex items-center gap-1.5 text-sm font-medium leading-none">
      {field.label}
      {required && <span className="text-destructive">*</span>}
      {serverOnly.length > 0 && (
        <span
          className="rounded bg-muted px-1 py-0.5 text-[10px] font-normal text-muted-foreground"
          title={`Checked server-side: ${serverOnly.join(', ')}`}
        >
          server-checked
        </span>
      )}
    </label>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import type { FieldOption, FormField, SpawnClient } from '@spawnflow/core';

export interface WidgetProps {
  field: FormField;
  value: unknown;
  onChange: (value: unknown) => void;
  onBlur: () => void;
  disabled: boolean;
  error?: string;
  client?: SpawnClient;
  subject?: string;
}

export type WidgetComponent = React.ComponentType<WidgetProps>;

const inputClass =
  'flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm transition-colors ' +
  'placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring ' +
  'disabled:cursor-not-allowed disabled:opacity-50';

function TextWidget({ field, value, onChange, onBlur, disabled }: WidgetProps) {
  const type = field.type === 'email' ? 'email' : field.type === 'password' ? 'password' : 'text';
  return (
    <input
      type={type}
      className={inputClass}
      value={(value as string) ?? ''}
      onChange={(e) => onChange(e.target.value)}
      onBlur={onBlur}
      disabled={disabled}
      autoComplete={field.type === 'password' ? 'new-password' : undefined}
    />
  );
}

function NumberWidget({ value, onChange, onBlur, disabled }: WidgetProps) {
  return (
    <input
      type="number"
      className={inputClass}
      value={value === undefined || value === null ? '' : String(value)}
      onChange={(e) => onChange(e.target.value === '' ? undefined : Number(e.target.value))}
      onBlur={onBlur}
      disabled={disabled}
    />
  );
}

function TextareaWidget({ value, onChange, onBlur, disabled }: WidgetProps) {
  return (
    <textarea
      className={inputClass + ' h-auto min-h-20'}
      rows={3}
      value={(value as string) ?? ''}
      onChange={(e) => onChange(e.target.value)}
      onBlur={onBlur}
      disabled={disabled}
    />
  );
}

// Wire-aware truthiness: legacy `on_off` boolean fields deliver 'on'/'off'
// strings, and 'off' is truthy to Boolean() — map the known wire encodings
// explicitly instead. Submission stays a real boolean (the contract's boolean
// type); the server converts back to the wire format.
function isCheckedValue(value: unknown): boolean {
  if (typeof value === 'string') {
    return value === 'on' || value === '1' || value === 'true';
  }
  return value === true || value === 1;
}

function CheckboxWidget({ field, value, onChange, disabled }: WidgetProps) {
  return (
    <label className="flex items-center gap-2 text-sm">
      <input
        type="checkbox"
        className="h-4 w-4 rounded border-input accent-primary"
        checked={isCheckedValue(value)}
        onChange={(e) => onChange(e.target.checked)}
        disabled={disabled}
      />
      <span className="text-muted-foreground">{field.label}</span>
    </label>
  );
}

function SelectWidget({ field, value, onChange, onBlur, disabled }: WidgetProps) {
  return (
    <select
      className={inputClass}
      value={value === undefined || value === null ? '' : String(value)}
      onChange={(e) => onChange(e.target.value === '' ? undefined : e.target.value)}
      onBlur={onBlur}
      disabled={disabled}
    >
      <option value="">— select —</option>
      {(field.options ?? []).map((option) => (
        <option key={String(option.value)} value={String(option.value)}>
          {option.label}
        </option>
      ))}
    </select>
  );
}

function DateWidget({ field, value, onChange, onBlur, disabled }: WidgetProps) {
  return (
    <input
      type={field.type === 'datetime' ? 'datetime-local' : 'date'}
      className={inputClass}
      value={(value as string) ?? ''}
      onChange={(e) => onChange(e.target.value)}
      onBlur={onBlur}
      disabled={disabled}
    />
  );
}

/**
 * Async searchable select for relation fields, backed by the options
 * endpoint (debounced q search, load-more pagination).
 */
function ComboboxWidget({ field, value, onChange, disabled, client, subject }: WidgetProps) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [options, setOptions] = useState<FieldOption[]>([]);
  const [nextPage, setNextPage] = useState<number | null>(null);
  const [selectedLabel, setSelectedLabel] = useState<string | null>(null);
  const rootRef = useRef<HTMLDivElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout>>();

  const load = async (q: string, page = 1, append = false) => {
    if (!client || !subject) return;
    const result = await client.options(subject, field.name, { q: q || undefined, page });
    setOptions((prev) => (append ? [...prev, ...result.options] : result.options));
    setNextPage(result.next_page);
  };

  useEffect(() => {
    if (!open) return;
    clearTimeout(timer.current);
    timer.current = setTimeout(() => void load(query), query ? 200 : 0);
    return () => clearTimeout(timer.current);
  }, [open, query]);

  useEffect(() => {
    const close = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, []);

  const current = selectedLabel ?? (value !== undefined && value !== null ? `#${value}` : null);

  return (
    <div ref={rootRef} className="relative">
      <button
        type="button"
        className={inputClass + ' justify-between text-left'}
        onClick={() => setOpen((o) => !o)}
        disabled={disabled}
      >
        <span className={current ? '' : 'text-muted-foreground'}>{current ?? 'Select…'}</span>
      </button>
      {open && (
        <div className="absolute z-10 mt-1 w-full rounded-md border border-input bg-popover p-1 shadow-md">
          {field.relation?.searchable && (
            <input
              autoFocus
              className={inputClass + ' mb-1'}
              placeholder="Search…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
          )}
          <ul className="max-h-48 overflow-auto text-sm">
            {options.length === 0 && <li className="px-2 py-1.5 text-muted-foreground">No results</li>}
            {options.map((option) => (
              <li key={String(option.value)}>
                <button
                  type="button"
                  className="w-full rounded-sm px-2 py-1.5 text-left hover:bg-accent"
                  onClick={() => {
                    onChange(option.value);
                    setSelectedLabel(option.label);
                    setOpen(false);
                  }}
                >
                  {option.label}
                </button>
              </li>
            ))}
            {nextPage !== null && (
              <li>
                <button
                  type="button"
                  className="w-full rounded-sm px-2 py-1.5 text-left text-muted-foreground hover:bg-accent"
                  onClick={() => void load(query, nextPage, true)}
                >
                  Load more…
                </button>
              </li>
            )}
          </ul>
        </div>
      )}
    </div>
  );
}

export const defaultWidgets: Record<string, WidgetComponent> = {
  input: TextWidget,
  password: TextWidget,
  textarea: TextareaWidget,
  number: NumberWidget,
  checkbox: CheckboxWidget,
  switch: CheckboxWidget,
  select: SelectWidget,
  combobox: ComboboxWidget,
  datepicker: DateWidget,
  datetimepicker: DateWidget,
};
